//! One command path for the desktop, terminal and batch automation.
use std::{collections::BTreeSet,path::Path};
use crate::{kernel::{number,Shape},model::{allocate,name_ok,Layer,Outcome,Session,State},Error,Result};
pub const HELP:&[(&str,&str,&str)]=&[
("Box","Box x,y,z width depth height","Create an exact B-rep box"),("Sphere","Sphere x,y,z radius","Create a sphere"),("Cylinder","Cylinder x,y,z radius height","Create a Z-axis cylinder"),("Cone","Cone x,y,z bottom_radius top_radius height","Create a cone or frustum"),("Torus","Torus x,y,z major_radius minor_radius","Create a ring torus"),("Circle","Circle x,y,z radius","Create a closed XY-plane wire"),
("Polyline","Polyline [closed] x,y,z x,y,z ...","Create a straight-segment wire"),("Curve","Curve x,y,z x,y,z ...","Interpolate a B-spline through points"),("NurbsCurve","NurbsCurve degree x,y,z,weight ...","Create an open-uniform rational B-spline"),("ExtrudeCrv","ExtrudeCrv id dx,dy,dz","Extrude a wire; closed planar wires produce solids"),("Revolve","Revolve id origin axis degrees","Revolve a profile around an axis"),("Loft","Loft solid|surface id id ...","Loft through ordered wire sections"),
("BooleanUnion","BooleanUnion a b [--keep]","Fuse; replace a and remove b, or keep inputs"),("BooleanDifference","BooleanDifference a b [--keep]","Subtract b from a"),("BooleanIntersection","BooleanIntersection a b [--keep]","Intersect two shapes; empty results are errors"),("Section","Section a b","Create section curves without deleting inputs"),("FilletEdge","FilletEdge id radius [edge_index ...]","Round selected 1-based edges, or all edges"),("ChamferEdge","ChamferEdge id distance [edge_index ...]","Chamfer selected edges, or all edges"),
("Move","Move id dx,dy,dz","Translate an editable object"),("Rotate","Rotate id origin axis degrees","Rotate an editable object"),("Scale","Scale id center factor","Uniform positive scaling"),("Mirror","Mirror id origin normal","Mirror in a plane"),("Copy","Copy id dx,dy,dz","Duplicate on the current layer"),("ArrayLinear","ArrayLinear id total_count step_vector","Keep the original and add translated copies"),("ArrayPolar","ArrayPolar id total_count center degrees","Circular array around Z; total includes original"),
("Delete","Delete id ...","Delete editable objects atomically"),("Hide","Hide id ...","Hide objects"),("Show","Show id ...","Show objects"),("Lock","Lock id ...","Lock objects"),("Unlock","Unlock id ...","Unlock object flags"),("Rename","Rename id \"name\"","Rename an editable object"),("Layer","Layer \"name\"","Add a layer and make it current"),("CurrentLayer","CurrentLayer id","Set the current construction layer"),("SetLayer","SetLayer object_id layer_id","Move an editable object to a layer"),("LayerColor","LayerColor id red green blue","Set sRGB color, channels 0..255"),("LayerVisible","LayerVisible id on|off","Toggle a layer's visibility"),("LayerLock","LayerLock id on|off","Toggle a layer's geometry lock"),
("Undo","Undo","Restore the previous document snapshot"),("Redo","Redo","Restore an undone edit"),("Save","Save \"file.arcocct\"","Atomically save exact B-reps, layers and names"),("Open","Open \"file.arcocct\"","Validate the entire project before replacement"),("ImportStep","ImportStep \"file.step\"","Import a STEP file as one compound object"),("ExportStep","ExportStep \"file.step\"","Atomically export visible geometry"),("ExportStl","ExportStl \"file.stl\"","Export visible face geometry as binary STL"),("New","New","Clear the document in one undoable edit"),("Demo","Demo","Build a small exact-geometry showcase in an empty document"),("List","List","Return JSON object measurements and document state"),("Help","Help [command]","Show syntax; units are millimeters")];
/// Quoted tokens preserve Windows backslashes. Inside double quotes only escaped quotes are special.
pub fn tokenize(line:&str)->Result<Vec<String>>{
    if line.len()>32768{return Err(Error::new("Command exceeds 32 KiB"));}let mut tokens=Vec::new();let mut token=String::new();let mut quote=None;let mut active=false;let mut chars=line.chars().peekable();
    while let Some(c)=chars.next(){if let Some(q)=quote {if c==q {quote=None;}else if c=='\\'&&q=='"'&&chars.peek()==Some(&'"'){chars.next();token.push('"');}else{token.push(c);}active=true;}
        else if c=='"'||c=='\''{quote=Some(c);active=true;}else if c.is_whitespace(){if active{tokens.push(std::mem::take(&mut token));active=false;}}else{token.push(c);active=true;}}
    if quote.is_some(){return Err(Error::new("Unclosed quote"));}if active{tokens.push(token);}if tokens.len()>1024{return Err(Error::new("Too many command arguments"));}Ok(tokens)
}
fn count(a:&[String],n:usize)->Result<()>{if a.len()==n{Ok(())}else{Err(Error::new(format!("Expected {n} arguments, received {}. Use Help <command>.",a.len())))}}
fn at(a:&[String],i:usize)->Result<&str>{a.get(i).map(String::as_str).ok_or_else(||Error::new("Missing argument. Use Help <command>."))}
fn real(s:&str)->Result<f64>{number(s.parse().map_err(|_|Error::new(format!("Not a number: {s}")))?)}
fn id(s:&str)->Result<u64>{s.trim_start_matches('#').parse().map_err(|_|Error::new(format!("Invalid ID: {s}")))}
fn point(s:&str)->Result<[f64;3]>{let a=s.split(',').collect::<Vec<_>>();if a.len()!=3{return Err(Error::new("Use x,y,z for points and vectors"));}Ok([real(a[0])?,real(a[1])?,real(a[2])?])}
fn switch(s:&str)->Result<bool>{match s.to_ascii_lowercase().as_str(){"on"|"true"|"1"=>Ok(true),"off"|"false"|"0"=>Ok(false),_=>Err(Error::new("Expected on or off"))}}
fn unique_ids(a:&[String])->Result<BTreeSet<u64>>{if a.is_empty(){return Err(Error::new("At least one object ID is required"));}a.iter().map(|s|id(s)).collect()}
fn new_shape(session:&mut Session,name:&str,shape:Shape)->Result<Outcome>{session.edit(|s,next|{let id=s.add(next,name,shape)?;Ok(Outcome::created(id,name))})}
pub fn execute(session:&mut Session,line:&str)->Result<Outcome>{
    let t=tokenize(line)?;let verb=t.first().ok_or_else(||Error::new("Enter a command"))?.trim_start_matches('_').to_ascii_lowercase();let a=&t[1..];
    match verb.as_str(){
    "box"=>{count(a,4)?;new_shape(session,"Box",Shape::cuboid(point(&a[0])?,[real(&a[1])?,real(&a[2])?,real(&a[3])?])?)},
    "sphere"=>{count(a,2)?;new_shape(session,"Sphere",Shape::sphere(point(&a[0])?,real(&a[1])?)?)},
    "cylinder"=>{count(a,3)?;new_shape(session,"Cylinder",Shape::cylinder(point(&a[0])?,real(&a[1])?,real(&a[2])?)?)},
    "cone"=>{count(a,4)?;new_shape(session,"Cone",Shape::cone(point(&a[0])?,real(&a[1])?,real(&a[2])?,real(&a[3])?)?)},
    "torus"=>{count(a,3)?;new_shape(session,"Torus",Shape::torus(point(&a[0])?,real(&a[1])?,real(&a[2])?)?)},
    "circle"=>{count(a,2)?;new_shape(session,"Circle",Shape::circle(point(&a[0])?,real(&a[1])?)?)},
    "polyline"=>{let closed=a.first().is_some_and(|s|s.eq_ignore_ascii_case("closed"));let points=a[usize::from(closed)..].iter().map(|s|point(s)).collect::<Result<Vec<_>>>()?;new_shape(session,"Polyline",Shape::polyline(&points,closed)?)},
    "curve"=>{let points=a.iter().map(|s|point(s)).collect::<Result<Vec<_>>>()?;new_shape(session,"Curve",Shape::interpolate(&points)?)},
    "nurbscurve"=>{let degree:u32=at(a,0)?.parse().map_err(|_|Error::new("Degree must be an integer"))?;let controls=a[1..].iter().map(|s|{let p=s.split(',').collect::<Vec<_>>();if p.len()!=4{return Err(Error::new("Controls use x,y,z,weight"));}Ok([real(p[0])?,real(p[1])?,real(p[2])?,real(p[3])?])}).collect::<Result<Vec<_>>>()?;new_shape(session,"NURBS curve",Shape::nurbs(degree,&controls)?)},
    "extrudecrv"=>{count(a,2)?;let shape=session.state().object(id(&a[0])?)?.shape.extrude(point(&a[1])?)?;new_shape(session,"Extrusion",shape)},
    "revolve"=>{count(a,4)?;let shape=session.state().object(id(&a[0])?)?.shape.revolve(point(&a[1])?,point(&a[2])?,real(&a[3])?)?;new_shape(session,"Revolution",shape)},
    "loft"=>{let solid=match at(a,0)?.to_ascii_lowercase().as_str(){"solid"=>true,"surface"=>false,_=>return Err(Error::new("Loft starts with solid or surface"))};let shapes=a[1..].iter().map(|s|Ok(session.state().object(id(s)?)?.shape.clone())).collect::<Result<Vec<_>>>()?;new_shape(session,"Loft",Shape::loft(&shapes,solid)?)},
    "booleanunion"|"booleandifference"|"booleanintersection"=>{
        if a.len()!=2&&a.len()!=3{return Err(Error::new("Expected two IDs and optional --keep"));}let left=id(&a[0])?;let right=id(&a[1])?;if left==right{return Err(Error::new("Choose two different objects"));}let keep=a.len()==3;if keep&&a[2]!="--keep"{return Err(Error::new("Unknown option; use --keep"));}
        session.edit(|s,next|{let l=s.object(left)?.shape.clone();let r=s.object(right)?.shape.clone();if !keep{s.editable(left)?;s.editable(right)?;}
            let shape=match verb.as_str(){"booleanunion"=>l.union(&r)?,"booleandifference"=>l.difference(&r)?,_=>l.intersection(&r)?};
            if keep{let id=s.add(next,"Boolean result",shape)?;Ok(Outcome::created(id,"Boolean result"))}else{s.replace(left,shape)?;s.objects.remove(&right);Ok(Outcome::message(format!("Updated #{left}; consumed #{right}")))}})
    },
    "section"=>{count(a,2)?;let l=&session.state().object(id(&a[0])?)?.shape;let r=&session.state().object(id(&a[1])?)?.shape;let shape=l.section(r)?;new_shape(session,"Section",shape)},
    "filletedge"|"chamferedge"=>{let target=id(at(a,0)?)?;let amount=real(at(a,1)?)?;let edges=a[2..].iter().map(|s|s.parse::<u32>().map_err(|_|Error::new("Edge indices must be positive integers"))).collect::<Result<Vec<_>>>()?;session.edit(|s,_|{let old=&s.editable(target)?.shape;let shape=if verb=="filletedge"{old.fillet(amount,&edges)?}else{old.chamfer(amount,&edges)?};s.replace(target,shape)?;Ok(Outcome::message(format!("Updated edges of #{target}")))})},
    "move"|"rotate"|"scale"|"mirror"=>{let target=id(at(a,0)?)?;session.edit(|s,_|{let old=&s.editable(target)?.shape;let shape=match verb.as_str(){"move"=>{count(a,2)?;old.translate(point(&a[1])?)?},"rotate"=>{count(a,4)?;old.rotate(point(&a[1])?,point(&a[2])?,real(&a[3])?)?},"scale"=>{count(a,3)?;old.scale(point(&a[1])?,real(&a[2])?)?},_=>{count(a,3)?;old.mirror(point(&a[1])?,point(&a[2])?)?}};s.replace(target,shape)?;Ok(Outcome::message(format!("Transformed #{target}")))})},
    "copy"=>{count(a,2)?;let object=session.state().object(id(&a[0])?)?;let name=format!("{} copy",object.name);let shape=object.shape.translate(point(&a[1])?)?;new_shape(session,&name,shape)},
    "arraylinear"|"arraypolar"=>{count(a,if verb=="arraylinear"{3}else{4})?;let target=id(&a[0])?;let total:usize=a[1].parse().map_err(|_|Error::new("Array count must be an integer"))?;if !(2..=128).contains(&total){return Err(Error::new("Array total count must be 2..128"));}let p=point(&a[2])?;let angle=if verb=="arraypolar"{real(&a[3])?}else{0.0};session.edit(|s,next|{let original=s.object(target)?.clone();let mut created=Vec::new();for i in 1..total {let shape=if verb=="arraylinear"{original.shape.translate(p.map(|v|v*i as f64))?}else{original.shape.rotate(p,[0.0,0.0,1.0],angle*i as f64/total as f64)?};let id=s.add(next,&format!("Array {i}"),shape)?;created.push(id);}Ok(Outcome{message:format!("Created {} copies",total-1),created})})},
    "delete"=>{let ids=unique_ids(a)?;session.edit(|s,_|{for id in &ids{s.editable(*id)?;}for id in &ids{s.objects.remove(id);}Ok(Outcome::message(format!("Deleted {} objects",ids.len())))})},
    "hide"|"show"|"lock"|"unlock"=>{let ids=unique_ids(a)?;session.edit(|s,_|{for id in &ids{s.object(*id)?;}for id in &ids{if let Some(o)=s.objects.get_mut(id){match verb.as_str(){"hide"=>o.visible=false,"show"=>o.visible=true,"lock"=>o.locked=true,_=>o.locked=false}}}Ok(Outcome::message(format!("{verb}: {} objects",ids.len())))})},
    "rename"=>{count(a,2)?;let target=id(&a[0])?;name_ok(&a[1])?;session.edit(|s,_|{s.editable(target)?;if let Some(o)=s.objects.get_mut(&target){o.name=a[1].clone();}Ok(Outcome::message("Renamed object"))})},
    "layer"=>{count(a,1)?;name_ok(&a[0])?;session.edit(|s,next|{if s.layers.len()>=256{return Err(Error::new("Layer limit reached"));}let id=allocate(next)?;s.layers.insert(id,Layer{id,name:a[0].clone(),color:[150,170,190],visible:true,locked:false});s.current_layer=id;Ok(Outcome::message(format!("Created layer #{id}")))})},
    "currentlayer"=>{count(a,1)?;let target=id(&a[0])?;session.edit(|s,_|{if !s.layers.contains_key(&target){return Err(Error::new("Layer does not exist"));}s.current_layer=target;Ok(Outcome::message(format!("Current layer #{target}")))})},
    "setlayer"=>{count(a,2)?;let object=id(&a[0])?;let layer=id(&a[1])?;session.edit(|s,_|{s.editable(object)?;if s.layers.get(&layer).is_none_or(|l|l.locked){return Err(Error::new("Target layer is missing or locked"));}if let Some(o)=s.objects.get_mut(&object){o.layer=layer;}Ok(Outcome::message("Changed object layer"))})},
    "layercolor"|"layervisible"|"layerlock"=>{let target=id(at(a,0)?)?;count(a,if verb=="layercolor"{4}else{2})?;session.edit(|s,_|{let l=s.layers.get_mut(&target).ok_or_else(||Error::new("Layer does not exist"))?;match verb.as_str(){"layercolor"=>{let c=a[1..].iter().map(|s|s.parse::<u8>().map_err(|_|Error::new("Color channels must be 0..255"))).collect::<Result<Vec<_>>>()?;l.color=[c[0],c[1],c[2]];},"layervisible"=>l.visible=switch(&a[1])?,_=>l.locked=switch(&a[1])?};Ok(Outcome::message("Updated layer"))})},
    "undo"=>{count(a,0)?;session.undo()},"redo"=>{count(a,0)?;session.redo()},"save"=>{count(a,1)?;session.save(Path::new(&a[0]))},"open"=>{count(a,1)?;session.open(Path::new(&a[0]))},
    "importstep"=>{count(a,1)?;let path=Path::new(&a[0]);if std::fs::metadata(path)?.len()>64*1024*1024{return Err(Error::new("STEP file exceeds 64 MiB input limit"));}let shape=Shape::import_step(&a[0])?;let name=path.file_stem().and_then(|s|s.to_str()).unwrap_or("Imported STEP");new_shape(session,name,shape)},
    "exportstep"|"exportstl"=>{count(a,1)?;session.export(Path::new(&a[0]),verb=="exportstl")},"new"=>{count(a,0)?;session.edit(|s,_|{*s=State::default();Ok(Outcome::message("New document; Undo restores the previous document"))})},"demo"=>{count(a,0)?;demo(session)},
    "list"=>{count(a,0)?;Ok(Outcome::message(serde_json::to_string_pretty(&session.summary()?)?))},
    "help"=>{if a.len()>1{return Err(Error::new("Help takes at most one command name"));}let filter=a.first().map(|s|s.to_ascii_lowercase());let text=HELP.iter().filter(|h|filter.as_ref().is_none_or(|f|h.0.eq_ignore_ascii_case(f))).map(|h|format!("{}\n  {}",h.1,h.2)).collect::<Vec<_>>().join("\n");if text.is_empty(){Err(Error::new("Unknown command"))}else{Ok(Outcome::message(text))}},
    _=>Err(Error::new(format!("Unknown command '{verb}'. Use Help to see implemented commands."))),}
}
pub fn demo(session:&mut Session)->Result<Outcome>{
    if !session.state().objects.is_empty(){return Err(Error::new("Demo requires an empty document. Save your work before New."));}
    session.edit(|s,next|{let plate=Shape::cuboid([0.0,0.0,0.0],[60.0,42.0,8.0])?.fillet(2.0,&[])?;let plate=plate.difference(&Shape::cylinder([18.0,21.0,-1.0],5.0,10.0)?)?.difference(&Shape::cylinder([42.0,21.0,-1.0],5.0,10.0)?)?;let mut created=vec![s.add(next,"Precision plate",plate)?];
        let ring_layer=allocate(next)?;s.layers.insert(ring_layer,Layer{id:ring_layer,name:"Warm metal".into(),color:[216,158,88],visible:true,locked:false});s.current_layer=ring_layer;created.push(s.add(next,"Torus study",Shape::torus([89.0,21.0,18.0],15.0,4.0)?.rotate([89.0,21.0,18.0],[1.0,0.0,0.0],55.0)?)?);
        let shell_layer=allocate(next)?;s.layers.insert(shell_layer,Layer{id:shell_layer,name:"Surface study".into(),color:[133,150,220],visible:true,locked:false});s.current_layer=shell_layer;let sections=[Shape::circle([25.0,78.0,0.0],16.0)?,Shape::circle([29.0,78.0,19.0],10.0)?,Shape::circle([23.0,80.0,39.0],14.0)?];created.push(s.add(next,"Loft study",Shape::loft(&sections,true)?)?);s.current_layer=0;Ok(Outcome{message:"Created exact B-rep plate, transformed torus and solid loft".into(),created})})
}
